DELETE FROM user_chat_thinking_history
WHERE user_message_id IN (
    SELECT id
    FROM user_chat_history
    WHERE user_world_id = #{userWorldId}
      AND id > #{maxChatHistoryId}
)

DELETE FROM user_chat_tool_call
WHERE user_message_id IN (
    SELECT id
    FROM user_chat_history
    WHERE user_world_id = #{userWorldId}
      AND id > #{maxChatHistoryId}
)

DELETE FROM user_chat_history
WHERE user_world_id = #{userWorldId}
  AND id > #{maxChatHistoryId}

DELETE FROM user_character_favor_log
WHERE user_world_id = #{userWorldId}
  AND id > #{maxFavorLogId}

DELETE FROM user_event_log
WHERE user_world_id = #{userWorldId}
  AND id > #{maxUserEventLogId}

DELETE FROM world_event_log
WHERE user_world_id = #{userWorldId}
  AND id > #{maxWorldEventLogId}

DELETE FROM world_story_event_character character_link
USING world_story_event story_event
WHERE character_link.story_event_id = story_event.id
  AND story_event.user_world_id = #{userWorldId}
  AND character_link.id > #{maxStoryEventCharacterId}

DELETE FROM world_story_event
WHERE user_world_id = #{userWorldId}
  AND id > #{maxStoryEventId}

DELETE FROM user_chat_history
WHERE id IN

    #{id}

DELETE FROM user_character_favor_log
WHERE user_world_id = #{userWorldId}
  AND character_id = #{characterId}
  AND binding_chat = #{bindingChat}
